function applySetting(key,value){if(flight)return;try{const next=editSymmetrySetting(parts,selected,key,value,linkSymmetry);checkpoint();parts=next;renderInspector();updateInfo();renderAssemblyTree();}catch(e){notify(e.message);}}
function deleteSelected(){if(!selected||flight)return;checkpoint();const ids=descendants(parts,selected);parts=normalizeSymmetry(parts.filter(p=>!ids.has(p.id)));for(const p of parts)if(ids.has(p.dockPartner))delete p.dockPartner;selected=null;rebuild();notify(`${ids.size} 部品を取り外しました`);}
gizmo.addEventListener('dragging-changed',e=>{controls.enabled=!e.value;if(e.value){saveDrag=structuredClone(parts);}else if(saveDrag){try{const next=editSymmetryPose(saveDrag,selected,dragPose(),linkSymmetry);checkpoint();parts=next;}catch(error){notify(error.message);}saveDrag=null;rebuild();}});gizmo.addEventListener('objectChange',()=>{if(saveDrag){try{for(const p of editSymmetryPose(saveDrag,selected,dragPose(),linkSymmetry)){if(p.id===selected)continue;const o=objects.get(p.id);o.position.fromArray(p.p);o.rotation.set(...p.r);}}catch{}}highlight.update();updateWorkshop();});
function cancelPlacement(){if(movingBranch)for(const id of movingBranch.ids){const obj=objects.get(id);if(obj)obj.visible=true;}movingBranch=null;branchDraft=null;$('#symmetry').disabled=false;placing=null;pendingPose=null;if(ghost){scene.remove(ghost);ghost.traverse(m=>{if(m.isMesh){const list=Array.isArray(m.material)?m.material:[m.material];list.forEach(x=>x.dispose());}});ghost=null;}disposeMarkers();$('#placement').hidden=true;$$('.partcard').forEach(b=>b.classList.remove('active'));}
function beginPlacement(type,branch=null,moving=false){if(flight)return;clearInterferenceHighlight();cancelPlacement();branchDraft=branch;if(moving){movingBranch={id:branch.rootId,ids:new Set(branch.parts.map(p=>p.id)),before:snapshot(),parent:parts.find(p=>p.id===branch.rootId).parent||null};for(const id of movingBranch.ids)objects.get(id).visible=false;highlight.visible=false;}$('#symmetry').disabled=!!branch;gizmo.detach();placing=type;ghost=branch?branchGhost(branch):cloneModel(type);ghost.traverse(o=>{if(o.isMesh){const tint=m=>{m=m.clone();m.transparent=true;m.opacity=.5;m.depthWrite=false;return m;};o.material=Array.isArray(o.material)?o.material.map(tint):tint(o.material);o.castShadow=false;}});scene.add(ghost);ghost.visible=false;$('#placement').hidden=false;$('#placement').firstChild.textContent=(moving?'付け替え '+branch.parts.length+' 部品':branch?'枝 '+branch.parts.length+' 部品（1組ずつ）':PARTS[type].name)+' · 取付位置をクリック · Escで取消 ';$$('.partcard').forEach(b=>b.classList.toggle('active',b.dataset.type===type));showNodes();}
function pointer(e){const r=canvas.getBoundingClientRect();mouse.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);raycaster.setFromCamera(mouse,camera);}
function hitPart(){const hits=raycaster.intersectObjects([...objects.values()].filter(o=>!movingBranch?.ids.has(o.userData.partId)),true);for(const h of hits){let o=h.object;while(o&&!o.userData.partId)o=o.parent;if(o)return {...h,id:o.userData.partId,root:o};}return null;}
function rejectNodePlacement(message){pendingPose=null;ghost.visible=false;$('#placement').firstChild.textContent=message+' · Escで取消 ';}
function posePlacement(e){if(!placing)return;pointer(e);const hit=hitPart(),kind=$('#attach').value;if(movingBranch&&!hit&&(kind==='node'||kind==='surface')){pendingPose=null;ghost.visible=false;return;}let pos=new T.Vector3(),q=new T.Quaternion(),parent=hit?.id??null,attachment={mode:hit&&kind==='surface'?'surface':'free'};const horizontal=bayMode==='sph';if(branchDraft)q.setFromEuler(new T.Euler(...branchDraft.parts.find(p=>p.id===branchDraft.rootId).r));else if(horizontal)q.setFromAxisAngle(new T.Vector3(1,0,0),Math.PI/2);
 if(hit&&kind==='node'){let best=null,dist=Infinity;const used=occupiedNodes(parts.filter(p=>!movingBranch?.ids.has(p.id)));hit.root.updateWorldMatrix(true,false);for(const [index,n] of nodes(parts.find(p=>p.id===hit.id).type).entries()){if(!nodeAvailable(used,hit.id,index))continue;const pt=hit.root.localToWorld(new T.Vector3(...n.slice(0,3))),d=pt.distanceTo(hit.point);if(d<dist){dist=d;best={index,point:pt,normal:new T.Vector3(...n.slice(3)).transformDirection(hit.root.matrixWorld)};}}
 if(!best){rejectNodePlacement('この部品の接続点はすべて使用済みです');return;}const anchor=new T.Vector3(),internal=branchDraft?occupiedNodes(branchDraft.parts):new Map();let ownNode=-1,score=-Infinity;if(placing==='wing'||placing==='fin')q.setFromUnitVectors(new T.Vector3(1,0,0),best.normal);else q.copy(hit.root.quaternion);for(const [index,n]of nodes(placing).entries()){if(branchDraft&&!nodeAvailable(internal,branchDraft.rootId,index))continue;const normal=new T.Vector3(...n.slice(3)).applyQuaternion(q),value=normal.dot(best.normal.clone().negate());if(value>score){score=value;ownNode=index;anchor.set(...n.slice(0,3));}}if(ownNode<0||score<1-1e-6){rejectNodePlacement('取出した枝の取付側に空いた接続点がありません');return;}pos.copy(best.point).sub(anchor.applyQuaternion(q));attachment={mode:'node',parentNode:best.index,ownNode};
 }else if(hit&&kind==='surface'){const normal=hit.face.normal.clone().transformDirection(hit.object.matrixWorld);const source=placing==='wing'?new T.Vector3(1,0,0):new T.Vector3(0,1,0);q.setFromUnitVectors(source,normal);pos.copy(hit.point);if(placing!=='wing')pos.addScaledVector(normal,PARTS[placing].size[1]/2);
 }else{const plane=new T.Plane(new T.Vector3(0,1,0),-workshopFloor);if(!raycaster.ray.intersectPlane(plane,pos))return;pos.y=workshopFloor+(horizontal?PARTS[placing].size[2]/2:PARTS[placing].size[1]/2);parent=movingBranch?movingBranch.parent:selected||parts[0]?.id||null;if($('#snap').checked)pos.divideScalar(.25).round().multiplyScalar(.25);if(branchDraft){ghost.position.set(0,0,0);ghost.quaternion.copy(q);ghost.updateMatrixWorld(true);pos.y=workshopFloor-new T.Box3().setFromObject(ghost).min.y;}}
 ghost.position.copy(pos);ghost.quaternion.copy(q);ghost.visible=true;pendingPose={pos,q,parent,attachment};$('#placement').firstChild.textContent=(branchDraft?'枝 '+branchDraft.parts.length+' 部品':PARTS[placing].name)+' · 取付位置をクリック · Escで取消 ';}
function place(){if(!pendingPose)return;if(branchDraft){try{if(movingBranch&&snapshot()!==movingBranch.before)throw Error('設計が変更されています。Escで取消してから付け替え直してください');const moving=!!movingBranch,rotation=new T.Euler().setFromQuaternion(pendingPose.q),pose={position:pendingPose.pos.toArray(),rotation:[rotation.x,rotation.y,rotation.z],parent:pendingPose.parent,attachment:pendingPose.attachment},result=moving?moveBranch(parts,movingBranch.id,pose):placeBranch(parts,branchDraft,pose);checkpoint();parts=result.parts;selected=result.rootId;cancelPlacement();rebuild();notify(result.count+'部品の枝を'+(moving?'付け替えました':'複製しました'));}catch(e){notify(e.message);}return;}const sym=$('#symmetry').value,count=sym==='mirror'?2:+sym;if(parts.length+count>400){notify('部品上限は400です');return;}let created=[];for(let i=0;i<count;i++){const pos=pendingPose.pos.clone(),q=pendingPose.q.clone();if(sym==='mirror'&&i){pos.x=-pos.x;const matrix=new T.Matrix4().makeRotationFromQuaternion(q),reflect=new T.Matrix4().makeScale(-1,1,1);matrix.premultiply(reflect).multiply(reflect);q.setFromRotationMatrix(matrix);if(placing==='wing')q.multiply(new T.Quaternion().setFromAxisAngle(new T.Vector3(0,1,0),Math.PI));}else if(i){const a=i*2*Math.PI/count,axis=bayMode==='vab'?new T.Vector3(0,1,0):new T.Vector3(0,0,1),rot=new T.Quaternion().setFromAxisAngle(axis,a);pos.applyQuaternion(rot);q.premultiply(rot);}const e=new T.Euler().setFromQuaternion(q);created.push({id:crypto.randomUUID(),type:placing,p:pos.toArray(),r:[e.x,e.y,e.z],parent:pendingPose.parent,stage:0,attachment:structuredClone(pendingPose.attachment)});}try{if(pendingPose.attachment.mode==='node'){created=created.map(p=>bindMatchingNode(parts,p));assertNodeAttachments([...parts,...created],created.map(p=>p.id));}}catch(e){notify(e.message);return;}checkpoint();if(count>1){const group=crypto.randomUUID();for(let i=0;i<created.length;i++){created[i].symmetryGroup=group;created[i].symmetryFrame=placementSymmetryFrame(sym,bayMode,i,count);}}parts.push(...created);selected=created[0].id;rebuild();showNodes();notify(`${PARTS[placing].name} ×${count} を取り付けました`);}
canvas.addEventListener('pointerdown',e=>{pointerDown={x:e.clientX,y:e.clientY,button:e.button,wasGizmo:!!gizmo.axis};});canvas.addEventListener('pointermove',e=>{if(!flight)posePlacement(e);});canvas.addEventListener('pointerup',e=>{if(!pointerDown||pointerDown.button!==0||Math.hypot(e.clientX-pointerDown.x,e.clientY-pointerDown.y)>5||pointerDown.wasGizmo||gizmo.dragging||flight)return;if(placing){posePlacement(e);place();}else{pointer(e);select(hitPart()?.id??null);}});canvas.addEventListener('contextmenu',e=>e.preventDefault());
const parachuteVisuals=new Map();let chuteFramed=false;let launchPilot=null;const flightFocus=new T.Vector3();
let trackedDebris=null;const debrisVisuals=new Map();
function allDebris(f){return f.detached.flatMap(child=>[child,...allDebris(child)]);}
function vesselCenter(f){return statistics(f.parts,f.fuel,f.ballast,f.thermal).com.applyQuaternion(f.q).add(f.pos);}
function updateDebrisVisuals(){for(const f of allDebris(flight)){let group=debrisVisuals.get(f);if(!group){group=new T.Group();for(const p of f.parts){const o=makePartVisual(p);if(PARTS[p.type].thrust&&!PARTS[p.type].water){const flame=new T.Mesh(new T.ConeGeometry(.23,1.3,16),new T.MeshBasicMaterial({color:'#ffba60',transparent:true,opacity:.8,depthWrite:false}));flame.rotation.z=Math.PI;flame.position.y=-PARTS[p.type].size[1]/2-.5;const target=o.userData.gimbal||o;if(o.userData.gimbal)flame.position.y-=PARTS[p.type].gimbalPivot[1];target.add(flame);o.userData.debrisFlame=flame;}group.add(o);}testWorld.add(group);debrisVisuals.set(f,group);group.userData.canopies=new Map();for(const p of f.parts)if(PARTS[p.type].parachute){const canopy=cloneModel('parachute-open');testWorld.add(canopy);group.userData.canopies.set(p.id,canopy);}}for(const [id,canopy]of group.userData.canopies){const state=f.chutes.get(id),p=f.parts.find(p=>p.id===id);canopy.visible=!!p&&!!state&&state.fraction>0;if(canopy.visible){canopy.position.fromArray(p.p).applyQuaternion(f.q).add(f.pos);canopy.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),bodyUp(canopy.position,f.universalTime));const scale=Math.sqrt(state.fraction);canopy.scale.set(scale,.45+.55*scale,scale);}}group.position.copy(f.pos);group.quaternion.copy(f.q);for(const o of group.children){const id=o.userData.partId;updateRCSVisual(o,f);if(o.userData.debrisFlame){o.userData.debrisFlame.visible=(f.engineThrust.get(id)||0)>1&&!f.crashed;o.userData.debrisFlame.scale.y=.5+f.throttle;}if(o.userData.hinge)o.userData.hinge.rotation.x=f.deflections.get(id)||0;if(o.userData.gimbal){const g=f.gimbals.get(id);o.userData.gimbal.rotation.set(g?.x||0,0,g?.z||0);}if(o.userData.rollingVisual){const wheel=f.wheelMotion.get(id);o.userData.steeringVisual.rotation.y=wheel?.steer||0;o.userData.rollingVisual.rotation.x=wheel?.angle||0;}}}}
function updateDebrisList(){const children=allDebris(flight),list=$('#debrisList');list.replaceChildren();$('#debrisCount').textContent=children.length;for(const [index,f]of children.entries()){const row=document.createElement('div'),text=document.createElement('small'),button=document.createElement('button');text.textContent=(f.vesselName||'機体 '+(index+1))+' · '+f.parts.length+'部品 · '+((f.orbit?.altitude||0)/1000).toFixed(1)+' km · 軌道 '+(f.orbit?.speed??0).toFixed(0)+' m/s · 燃料 '+Math.round(f.fuelRatio*100)+'% · 電力 '+powerTotals(f.parts,f.charge).stored.toFixed(0)+' EC'+(f.crashed?' · 損傷':f.landed?' · 着地':'');button.textContent=trackedDebris===f?'追跡中':'追跡';button.onclick=()=>{trackedDebris=f;const target=vesselCenter(f);controls.target.copy(target);camera.position.copy(target).add(new T.Vector3(14,10,18));flightFocus.copy(target);updateDebrisList();};const take=document.createElement('button');take.textContent=canControl(f)?'操縦':'制御不可';take.disabled=!canControl(f);take.onclick=()=>switchVessel(f);const targetButton=document.createElement('button');targetButton.textContent=flight.navigationTarget===f?'目標指定中':'目標にする';targetButton.onclick=()=>{setTarget(flight,flight,f);updateNavigation();updateDebrisList();};row.append(text,button,take,targetButton);list.append(row);}}
