function flightCenter(){return statistics(flight.parts,flight.fuel,flight.ballast,flight.thermal).com.applyQuaternion(flight.q).add(flight.pos);}
function frame(){setCameraUp(flight?bodyUp(flightCenter(),flight.universalTime):new T.Vector3(0,1,0));const bounds=new T.Box3().setFromObject(craftRoot);if(bounds.isEmpty())return;if(!flight){const fit=workshopFrame(bounds,camera.fov,camera.aspect);controls.maxDistance=fit.maxDistance;scene.fog=new T.Fog('#293c49',fit.fogNear,fit.fogFar);controls.target.copy(fit.target);camera.position.copy(fit.target).add(new T.Vector3(1,.65,1.3).normalize().multiplyScalar(fit.distance));controls.update();return;}const fit=workshopFrame(bounds,camera.fov,camera.aspect);flightFocus.copy(flightCenter());controls.target.copy(fit.target);camera.position.copy(fit.target).add(new T.Vector3(1,.65,1.3).normalize().multiplyScalar(fit.distance*1.5).applyQuaternion(new T.Quaternion().setFromUnitVectors(new T.Vector3(0,1,0),bodyUp(flightCenter(),flight.universalTime))));controls.update();}
