const examples={'lunar-surface-expedition':['Selene Expedition / 21','月面往復ロケット（上級）','55部品 · 地上から月面へ · 着陸・再離陸・カプセル帰還 · 燃料余裕小','land'],'lunar-expedition':['Luna Expedition / 20','月往復ロケット','地上から出発 · 3段式 · 月周回とカプセル帰還','land'],'lunar-return':['Luna Return / 19','月帰還カプセル','月周回から帰還 · 熱シールド・分離・パラシュート','moon-orbit'],moonlander:['Selene Ascent / 18','月面離陸練習機','月面から出発 · 姿勢と推力を手動操作 · 月周回へ','moon-surface'],lander:['Selene / 17','四脚月着陸機','月高度20 kmから · 逆行減速と天頂降下 · 四脚で接地','moon-orbit'],transfer:['Lunar Pathfinder / 16','月遷移練習機','母星80 kmから出発 · 60秒後に手動噴射 · 月フライバイ','transfer'],reentry:['Entry Lab / 15','再突入試験機','熱シールド · SAS逆行で保護 · Hでパラシュート待機','entry'],docking:['Docking Lab / 13','ドッキング試験機','結合済み2機 · 右パネルで再分離と再結合','orbit'],rendezvous:['Rendezvous / 12','相対航法試験機','Spaceを2回で分離 · 相手を目標指定 · RCSで接近','orbit'],rcs:['Attitude Lab / 11','RCS試験機','ホイール無効 · RでRCS · IJKLUOで並進','orbit'],twin:['Gemini / 10','双子探査機','Spaceを2回で分離 · 他機体へ操縦切替','orbit'],recovery:['Recovery / 09','カプセル降下試験','高度1 km · パラシュートをHで待機','drop'],returner:['Pioneer Return / 08','帰還ロケット','2段式 · 熱シールド · パラシュート','land'],launcher:['Pioneer Heavy / 07','軌道投入ロケット','2段式 · 下段4基 · 上段1基','land'],rocket:['Pioneer / 01','ロケット','45 kN · 4枚フィン','land'],orbiter:['Surveyor / 02','宇宙探査機','無人コア · ソーラーパネル','land'],plane:['Swift / 03','ジェット機','独立操舵面 · 前輪1＋主脚2','runway'],rover:['Nomad / 04','ローバー','4輪駆動 · 無人探査','land'],boat:['Tern / 05','双胴艇','フロート · スクリュー','water'],sub:['Nautilus / 06','潜水艇','注排水タンク · 水中推進','water']};
$('#examples').onclick=()=>{if(flight)return;showModal('<div class="eyebrow">START FROM A BLUEPRINT</div><h2>最初の一機を選ぶ</h2><p>見本機を改造して、設計を試せます。現在の機体は「元に戻す」で復元できます。</p><div class="examplegrid">'+Object.entries(examples).map(([k,v])=>`<button data-example="${k}"><b>${v[1]}</b><span>${v[0]}<br>${v[2]}</span></button>`).join('')+'</div>');$$('[data-example]').forEach(b=>b.onclick=()=>{const k=b.dataset.example;checkpoint();parts=preset(k);$('#craftName').value=examples[k][0];setBay(['plane','boat','sub','rover'].includes(k)?'sph':'vab');$('#environment').value=examples[k][3];updateDepartureButton(document,$('#environment').value);selected=null;cancelPlacement();rebuild();frame();$('#modal').close();});};
$('#help').onclick=()=>showModal('<div class="eyebrow">WORKSHOP FIELD GUIDE</div><h2>設計から試験まで</h2><p>左の部品を選び、機体の取付位置をクリック。接続点・表面・自由配置を切り替え、対称配置で翼やブースターを取り付けられます。</p><div class="helpgrid"><b>右ドラッグ / ホイール</b><span>視点回転 / 拡大縮小</span><b>中ドラッグ</b><span>平行移動</span><b>G / E / Esc</b><span>移動 / 回転 / 配置取消・選択モード</span><b>X / Shift+X</b><span>対称数を増減</span><b>R / C</b><span>軸対称・鏡面切替 / スナップ切替</span><b>F / Delete</b><span>機体全体を表示 / 選択した接続枝を削除</span><b>Ctrl+Z / Ctrl+Y</b><span>元に戻す / やり直す</span><b>試験 → Space</b><span>点火 / 次のステージ実行</span><b>Shift / Ctrl</b><span>推力を上げる / 下げる</span><b>Z / X（飛行中）</b><span>全開 / スロットル0</span><b>W/S · A/D · Q/E</b><span>ピッチ · ヨー · ロール</span><b>T / ピッチトリム</b><span>SAS姿勢保持 / 舵の中立を調整</span><b>車輪 / 操作ON・OFF</b><span>始動後W/Sで前後進、A/Dで操向。下部のチェックで姿勢制御・車輪操舵・駆動を個別に切替。両方ONならW/Sは姿勢と駆動の両方へ作用。</span><b>バラスト</b><span>海面試験で注排水。増やすと重くなる</span></div><p>ジェット見本は全開で約30秒加速後、Sを約2秒押して機首上げ。舵は気流によって効き、低速では姿勢を変えにくくなります。黄色は重心、水色は水平・機首+Zでの空力中心近似。吹き下ろしなどの干渉は未計算です。</p><p>保存はこのブラウザ内。JSON出力で機体を持ち出せます。半径600 kmの球形惑星で、中心重力・軌道・電力・再突入熱を計算します。熱シールドの茶色の面を進行方向へ向け、パラシュートを熱から保護してください。カプセル見本はSAS逆行で遮熱、Hでパラシュートを待機させます。熱はゲーム用の近似で、部品間の熱伝導・破断応力・通常の機体間衝突は未実装。Δvは段別の真空参考値です。</p>');
