$('#save').onclick=()=>{try{localStorage.setItem('orbital-foundry-craft',JSON.stringify(craftData()));notify('このブラウザに機体を保存しました');}catch{notify('保存できませんでした。JSON出力を使ってください。');}};$('#load').onclick=()=>{if(flight)return;try{const s=localStorage.getItem('orbital-foundry-craft');if(!s){notify('保存された機体がありません');return;}loadData(JSON.parse(s));notify('保存した機体を読み込みました');}catch(e){notify(e.message);}};$('#export').onclick=()=>{const a=document.createElement('a');const url=URL.createObjectURL(new Blob([JSON.stringify(craftData(),null,2)],{type:'application/json'}));a.href=url;a.download=($('#craftName').value.replace(/[^\p{L}\p{N}_-]/gu,'_')||'craft')+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);};$('#import').onclick=()=>{if(!flight)$('#file').click();};$('#file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>1000000)throw Error('機体ファイルが大きすぎます');loadData(JSON.parse(await file.text()));notify('機体を読み込みました');}catch(e){notify(e.message);}$('#file').value='';};
function disposeWorld(){testWorld.traverse(o=>{if(o.userData.sharedAsset)return;o.geometry?.dispose();if(o.material){const mats=Array.isArray(o.material)?o.material:[o.material];mats.forEach(m=>m.dispose());}});testWorld.clear();}
let surfacePatch;
let moonGlobe,groundFacilities;function buildTestWorld(environment){disposeWorld();groundFacilities=new T.Group();testWorld.add(groundFacilities);const color=environment==='water'?'#164c64':'#627569';const globe=new T.Mesh(new T.SphereGeometry(PLANET.radius,256,128),mat(color,.05,.95));globe.position.copy(center);testWorld.add(globe);moonGlobe=new T.Mesh(new T.SphereGeometry(MOON.radius,192,96),mat('#92918d',0,1));moonGlobe.position.copy(bodyState(MOON,flight.universalTime).position);testWorld.add(moonGlobe);const geometry=new T.PlaneGeometry(4000,4000,64,64);geometry.rotateX(-Math.PI/2);const positions=geometry.attributes.position;for(let i=0;i<positions.count;i++){const x=positions.getX(i),z=positions.getZ(i);positions.setY(i,Math.sqrt(PLANET.radius**2-x*x-z*z)-PLANET.radius+.01);}geometry.computeVertexNormals();surfacePatch=new T.Mesh(geometry,mat(color,.05,.95));surfacePatch.receiveShadow=true;testWorld.add(surfacePatch);if(environment!=='water'){const runwayGeometry=new T.PlaneGeometry(18,1600,1,80);runwayGeometry.rotateX(-Math.PI/2);runwayGeometry.translate(0,0,650);const rp=runwayGeometry.attributes.position;for(let i=0;i<rp.count;i++)rp.setY(i,.025-(rp.getX(i)**2+rp.getZ(i)**2)/(2*PLANET.radius));runwayGeometry.computeVertexNormals();const runway=new T.Mesh(runwayGeometry,mat('#3a4245'));runway.receiveShadow=true;groundFacilities.add(runway);for(let z=-40;z<1400;z+=22)box(groundFacilities,[.25,.01,8],[0,.035-z*z/(2*PLANET.radius),z],mat('#d8d7bd'));}}
$('#clearTarget').onclick=()=>{if(flight){setTarget(flight,flight,null);updateNavigation();updateDebrisList();}};
function updateNavigation(){resolveTargets(flight);updateDocking();const relative=relativeState(flight,flight.navigationTarget);$('#targetInfo').textContent=relative?'目標まで '+relative.distance.toFixed(1)+' m · 相対速度 '+relative.speed.toFixed(2)+' m/s':'目標未指定';$('#targetDetail').textContent=relative?(relative.closing>=0?'接近 ':'離脱 ')+Math.abs(relative.closing).toFixed(2)+' m/s · '+(relative.braking?'減速方向まで '+(Math.acos(T.MathUtils.clamp(new T.Vector3(0,flight.rocketAxes?1:0,flight.rocketAxes?0:1).applyQuaternion(flight.q).dot(relative.braking),-1,1))*180/Math.PI).toFixed(0)+'° · 整列後 I でRCS噴射':'速度差 0.01 m/s以下 · 噴射を停止'):'';if(relative&&flight.portTranslationEnabled)$('#targetDetail').textContent='ポート基準の並進中 · 右のポート誘導で接近';$('#translationHelp').textContent=flight.portTranslationEnabled?'RCS並進: I/K 接近・離脱 · J/L 左右 · U/O 上下（目標ポート基準）':'RCS並進: I/K 前後 · J/L 左右 · U/O 上下（機体軸）';$('#clearTarget').hidden=!relative;const nav=drawNavball($('#navball'),flight.q,flight.rocketAxes,flightCenter(),flight.vel,flight.universalTime);$('#navPitch').textContent='PITCH '+nav.pitch.toFixed(0)+'° · ＋順行 / ×逆行（軌道基準）';$('#sasMode').value=flight.sasMode;}
function updateOrbit(){const o=flight.orbit||bodyOrbitState(flightCenter(),flight.vel,flight.universalTime),km=x=>Number.isFinite(x)?(x/1000).toFixed(1)+' km':'∞';$('#orbitInfo').textContent=o.body.name+' · '+(o.stable?'周回軌道':o.energy>=0?'脱出軌道':o.periapsis<0?'地表と交差':'大気と交差')+' · 遠点 '+km(o.apoapsis)+' · 近点 '+km(o.periapsis);$('#maneuverHud').textContent=flight.maneuver?(flight.maneuver.complete?'予定Δv到達 · Xで停止':'計画残り '+new T.Vector3(...flight.maneuver.remaining).length().toFixed(1)+' m/s · '+(flight.maneuver.time>=flight.time?'噴射まで ':'予定から ')+formatDuration(Math.abs(flight.maneuver.time-flight.time))):'';$('#orbitDetail').textContent='軌道速度 '+o.speed.toFixed(1)+' m/s · 円軌道速度 '+o.circularSpeed.toFixed(0)+' m/s · 重力 '+o.gravity.toFixed(2)+' m/s²';drawOrbit($('#orbitMap'),o);if(!$('#orbitOverlay').hidden)updateOrbitPlan(o);moonGlobe.position.copy(bodyState(MOON,flight.universalTime).position);groundFacilities.quaternion.copy(surfaceOrientation(flight.universalTime));groundFacilities.position.copy(fixedToInertial(new T.Vector3(0,PLANET.radius,0),flight.universalTime));const up=bodyUp(flight.pos,flight.universalTime);surfacePatch.visible=o.bodyId==='planet';surfacePatch.position.copy(up).multiplyScalar(o.body.radius).add(o.center);surfacePatch.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),up);scene.background.set('#02050d').lerp(new T.Color('#8eb5c8'),o.bodyId==='planet'?Math.max(0,1-o.altitude/70000):0);scene.fog=null;}

