$('#openOrbitMap').onclick=toggleOrbitMap;$('#closeOrbitMap').onclick=()=>$('#orbitOverlay').hidden=true;
for(const id of ['planEnabled','planLocation','planDeltaV'])$('#'+id).addEventListener('input',()=>{if(flight)updateOrbit();});
$('#fixManeuver').onclick=()=>{if(!flight)return;try{const value=$('#planDeltaV').value;if(value.trim()==='')throw Error('予定Δvを入力してください');const preview=maneuverPreview(flightCenter(),flight.vel,$('#planLocation').value,Number(value),flight.universalTime);flight.maneuver=createManeuverNode(preview,flight.time);$('#planEnabled').checked=false;updateOrbit();notify('噴射計画を固定しました。点火・停止は手動です。');}catch(e){notify(e.message);}};
$('#alignManeuver').onclick=()=>{if(!flight?.maneuver)return;launchPilot=null;flight.sas=true;flight.sasMode='maneuver';$('#sas').textContent='SAS ON';$('#sas').classList.add('active');};
