function updateOrbitPlan(o){const plan=apsisPlan(o);let preview=null;$('#maneuverResult').textContent='比較プレビューはOFFです。';if($('#planEnabled').checked){try{const value=$('#planDeltaV').value;if(value.trim()==='')throw new Error('予定Δvを入力してください');preview=maneuverPreview(flightCenter(),flight.vel,$('#planLocation').value,Number(value),flight.universalTime);const km=x=>Number.isFinite(x)?(x/1000).toFixed(1)+' km':'なし（脱出）';$('#maneuverResult').textContent='予定地点まで '+formatDuration(preview.time)+' · Δv '+preview.deltaV.toFixed(1)+' m/s\n予測遠点 '+km(preview.orbit.apoapsis)+' / 近点 '+km(preview.orbit.periapsis)+(preview.orbit.periapsis<0?'\n予測軌道は地表と交差します':preview.orbit.periapsis<preview.orbit.body.atmosphereTop?'\n予測軌道は大気と交差します':'');}catch(error){$('#maneuverResult').textContent=error.message;}}const node=flight.maneuver;$('#alignManeuver').disabled=!node;$('#clearManeuver').disabled=!node;$('#fixedManeuverStatus').textContent='計画なし';if(node){const remaining=new T.Vector3(...node.remaining).length(),dt=node.time-flight.time,forward=new T.Vector3(0,flight.rocketAxes?1:0,flight.rocketAxes?0:1).applyQuaternion(flight.q),angle=forward.angleTo(maneuverDirection(node))*180/Math.PI;$('#fixedManeuverStatus').textContent=(node.complete?'目標Δv到達：スロットルを切ってください':dt>=0?'噴射まで '+formatDuration(dt):'予定時刻から '+formatDuration(-dt))+'\n残り '+remaining.toFixed(1)+' m/s · 方向差 '+angle.toFixed(1)+'°';if(!preview)preview={orbit:bodyOrbitState(new T.Vector3(...node.position),new T.Vector3(...node.velocity),node.capture?.midTime??node.returnPlan?.midTime??node.departure?.midTime??node.universalTime??flight.universalTime+node.time-flight.time)};}drawOrbit($('#largeOrbitMap'),o,{detail:true,preview});$('#mapFlightState').textContent='現在 '+o.speed.toFixed(1)+' m/s · スロットル '+Math.round(flight.throttle*100)+'%';$('#orbitKind').textContent={circular:'ほぼ円軌道',ellipse:'楕円軌道',escape:'脱出軌道',radial:'半径方向の飛行'}[plan.kind];$('#orbitCaution').textContent=plan.caution;$('#orbitPeriod').textContent='公転周期 '+formatDuration(plan.period);for(const key of ['apoapsis','periapsis']){const point=plan[key],name=key==='apoapsis'?'遠点':'近点';$('#'+key+'Plan').textContent=point?name+' '+(point.altitude/1000).toFixed(1)+' km\n到達まで '+formatDuration(point.time)+'\n円軌道化：'+(point.deltaV===null?'地表内のため不可':(point.deltaV>=0?'順行 ':'逆行 ')+Math.abs(point.deltaV).toFixed(1)+' m/s'):name+'：'+(plan.kind==='circular'?'円軌道では方向が定まりません':'なし');}$('#orbitPlanNote').textContent=plan.kind==='escape'?'遠点はありません。近点の到達時間「—」は通過済み、または計算対象外です。':plan.kind==='circular'?'遠点・近点を指定する必要がない、ほぼ円形の軌道です。':'Δvはその遠点・近点で瞬間的に噴射する場合の目安です。現在位置での噴射量ではありません。';}

const exhaust=[];function startFlight(restored=null){trajectoryPanel.reset();if(!parts.length){notify('まず機体を組み立ててください');return;}if(!(restored instanceof Flight)&&!parts.some(p=>PARTS[p.type].control)){notify('試験には制御ユニットが必要です');return;}if(parts.filter(p=>!p.parent).length!==1){notify('独立した部品を接続してから試験してください');return;}cancelPlacement();clearInterferenceHighlight();gizmo.detach();highlight.visible=false;comMarker.visible=false;aeroMarker.visible=false;flight=restored instanceof Flight?restored:new Flight(parts,$('#environment').value,universalTime);if(!(restored instanceof Flight))flight.universalTime=universalTime;universalTime=flight.universalTime;if(worldRuntime)worldRuntime.replace(flight);else worldRuntime=new WorldRuntime(flight);updateFlightControls(document,flight);if(!(restored instanceof Flight))activeFlightName=$('#craftName').value;launchPilot=null;$('#autoLaunch').textContent='自動軌道投入（見本用）';$('#autoLaunch').hidden=!parts.some(p=>PARTS[p.type].decoupler)||['orbit','moon-orbit','moon-surface','transfer'].includes(flight.environment)||!flight.rocketAxes;physicsClock.reset();trackedDebris=null;debrisVisuals.clear();buildTestWorld(flight.environment);parachuteVisuals.clear();chuteFramed=false;for(const p of flight.parts)if(PARTS[p.type].parachute){const canopy=cloneModel('parachute-open');canopy.visible=false;testWorld.add(canopy);parachuteVisuals.set(p.id,canopy);}$('#armChutes').hidden=!parachuteVisuals.size;$('#autoReturn').hidden=['moon-orbit','moon-surface','transfer'].includes(flight.environment)||!parachuteVisuals.size||!flight.parts.some(p=>PARTS[p.type].decoupler)||!flight.parts.some(p=>PARTS[p.type].thrust);testWorld.visible=true;bay.visible=false;scene.background=new T.Color('#8eb5c8');scene.fog=new T.Fog('#9fbdc5',300,2000);document.body.classList.add('flying');$('#flightHud').hidden=false;$('#launch').disabled=true;$('#throttle').value=0;$('#ballast').value=0;$('#trim').value=0;$('#trimVal').textContent='0%';$('#sas').classList.add('active');$('#sas').textContent='SAS ON';$('#brake').classList.add('active');$('#brake').textContent='BRAKE ON';controls.maxDistance=2000000;$('#warp').value='1';$('#warpStatus').textContent='通常速度 · 1倍';showCoastBlocker(null);for(const p of parts){if(PARTS[p.type].thrust&&!PARTS[p.type].water){const flame=new T.Mesh(new T.ConeGeometry(.23,1.3,16),new T.MeshBasicMaterial({color:PARTS[p.type].air?'#76cdff':'#ffba60',transparent:true,opacity:.8,depthWrite:false}));flame.rotation.z=Math.PI;flame.position.y=-PARTS[p.type].size[1]/2-.5;flame.visible=false;const target=objects.get(p.id).userData.gimbal||objects.get(p.id);if(PARTS[p.type].gimbal)flame.position.y-=PARTS[p.type].gimbalPivot[1];target.add(flame);exhaust.push({id:p.id,mesh:flame});}}craftRoot.position.copy(flight.pos);craftRoot.quaternion.copy(flight.q);frame();updateInfo();if(flight.transferGuide)$('#inspector').scrollTop=0;notify(flight.environment==='moon-surface'?'月面で待機。右の再離陸手順を開き、Space点火・30%で上昇。':flight.environment==='moon-orbit'?'月の高度20 km円軌道から開始。月基準の速度を表示します。':flight.environment==='orbit'?'高度80 kmの初期円軌道から開始。無推力で周回します。':'Spaceで始動。車輪はW/Sで前後進、A/Dで操向。');}
function syncFlightControls(){for(const k of ['reactionEnabled','steeringEnabled','driveEnabled','rcsEnabled'])$('#'+k).checked=flight[k];$('#throttle').value=flight.throttle*100;$('#ballast').value=flight.ballast*100;$('#trim').value=flight.trim*100;$('#trimVal').textContent=Math.round(flight.trim*100)+'%';$('#sas').textContent='SAS '+(flight.sas?'ON':'OFF');$('#sas').classList.toggle('active',flight.sas);$('#brake').textContent='BRAKE '+(flight.brake?'ON':'OFF');$('#brake').classList.toggle('active',flight.brake);updateInfo();updateNavigation();updateOrbit();updateDebrisList();}
function switchVessel(target){try{const next=selectVessel(flight,target),blueprint=parts;keys.clear();launchPilot=null;exhaust.forEach(e=>{e.mesh.geometry.dispose();e.mesh.material.dispose();});exhaust.length=0;flight=next;parts=structuredClone(next.parts);rebuild();startFlight(next);parts=blueprint;syncFlightControls();notify('操縦対象を変更しました · '+(PARTS[flight.parts.find(p=>PARTS[p.type].control).type].name));}catch(e){notify(e.message);}}
function endFlight(){trajectoryPanel.reset();if(flight)universalTime=flight.universalTime;$('#dockingPanel').hidden=true;trackedDebris=null;debrisVisuals.clear();$('#orbitOverlay').hidden=true;launchPilot=null;flight?.dispose();flight=null;worldRuntime=null;exhaust.forEach(e=>{e.mesh.geometry.dispose();e.mesh.material.dispose();});exhaust.length=0;craftRoot.position.set(0,0,0);craftRoot.quaternion.identity();testWorld.visible=false;bay.visible=true;scene.background=new T.Color('#293c49');scene.fog=new T.Fog('#293c49',55,135);document.body.classList.remove('flying');$('#flightHud').hidden=true;$('#launch').disabled=false;controls.maxDistance=80;sun.position.set(12,24,12);sun.target.position.set(0,0,0);rebuild();frame();const environment=$('#environment').value;setBay(bayMode);$('#environment').value=environment;}
function stage(){if(!flight||!canControl(flight))return;const removed=flight.stageNext();updateFlightControls(document,flight);for(const id of removed){const o=objects.get(id);if(o)o.visible=false;}notify(`ステージ ${String(flight.stage).padStart(2,'0')} 実行${removed.size?' / '+removed.size+' 部品分離':''}`);$('#brake').classList.toggle('active',flight.brake);$('#brake').textContent='BRAKE '+(flight.brake?'ON':'OFF');}
for(const key of ['reactionEnabled','steeringEnabled','driveEnabled','rcsEnabled'])$('#'+key).onchange=e=>{if(flight)flight[key]=e.target.checked;e.target.blur();};
$('#armChutes').onclick=()=>{flight?.armParachutes();document.activeElement.blur();};$('#autoReturn').onclick=()=>{if(!flight)return;if((flight.orbit?.altitude||0)<70000){notify('帰還実演は高度70 km以上で開始してください');return;}launchPilot=new ReturnPilot();$('#autoLaunch').textContent='自動実演を解除';document.activeElement.blur();};
$('#sasMode').onchange=e=>{if(!flight)return;launchPilot=null;$('#autoLaunch').textContent='自動軌道投入（見本用）';flight.sasMode=(e.target.value==='maneuver'&&!flight.maneuver)||(TARGET_MODES.includes(e.target.value)&&!flight.navigationTarget)||(e.target.value==='dock'&&!flight.dockingPorts)?'hold':e.target.value;flight.holdQ=flight.q.clone();flight.sas=true;$('#sas').textContent='SAS ON';$('#sas').classList.add('active');e.target.blur();};
$('#autoLaunch').onclick=()=>{if(!flight)return;if(launchPilot){launchPilot=null;flight.throttle=0;$('#autoLaunch').textContent='自動軌道投入（見本用）';}else{launchPilot=new LaunchPilot();$('#autoLaunch').textContent='自動実演を解除';}document.activeElement.blur();};
const flightSaveKey='orbital-foundry-flight-v1';
function quickSave(){if(!flight)return;try{updateExploration();if(practiceSession){practiceSession.saveFlight(flightRecord());notify('練習中の飛行を一時保存しました。練習終了・再読込で破棄されます。');return;}const pilot=launchPilot?{kind:launchPilot instanceof ReturnPilot?'return':'launch',done:launchPilot.done,released:!!launchPilot.released}:null;localStorage.setItem(flightSaveKey,JSON.stringify(saveFlight(flight,{blueprint:parts.length?parts:flight.parts,name:flight.vesselName||activeFlightName||$('#craftName').value,pilot,worldHistory:parkedWorld?.history??[]})));notify('飛行を保存しました · T+ '+flight.time.toFixed(1)+'s');}catch(e){notify('飛行を保存できませんでした：'+e.message);}}
function quickLoad(){try{if(practiceSession){restoreFlight(practiceSession.loadFlight());return;}const raw=localStorage.getItem(flightSaveKey);if(!raw)throw Error('保存された飛行がありません');if(raw.length>2000000)throw Error('保存データが大きすぎます');const data=JSON.parse(raw);if(needsPhysicsMigration(data))localStorage.setItem(flightSaveKey+'-before-rotation-'+Date.now(),raw);restoreFlight(data);}catch(e){notify(e.message);}}
function restoreFlight(data){const draft={parts,name:$('#craftName').value,environment:$('#environment').value,bay:bayMode};let restored;try{validateCraft({version:1,parts:data.meta?.blueprint||data.parts});const pilot=data.meta?.pilot;if(pilot&&(!['return','launch'].includes(pilot.kind)||typeof pilot.done!=='boolean'||typeof pilot.released!=='boolean'))throw Error('自動実演の保存形式が不正です');const restoredWorld=worldFromFlight(data);restored=loadFlight(data);if(flight)endFlight();parkedWorld=restoredWorld;parts=structuredClone(restored.parts);$('#craftName').value=typeof data.meta?.name==='string'?data.meta.name.slice(0,80):'Restored flight';$('#environment').value=restored.environment;rebuild();startFlight(restored);activeFlightName=flight.vesselName||$('#craftName').value;parts=draft.parts;$('#craftName').value=draft.name;$('#environment').value=draft.environment;bayMode=draft.bay;for(const k of ['reactionEnabled','steeringEnabled','driveEnabled','rcsEnabled'])$('#'+k).checked=flight[k];$('#throttle').value=flight.throttle*100;$('#ballast').value=flight.ballast*100;$('#trim').value=flight.trim*100;$('#trimVal').textContent=Math.round(flight.trim*100)+'%';$('#sas').textContent='SAS '+(flight.sas?'ON':'OFF');$('#sas').classList.toggle('active',flight.sas);$('#brake').textContent='BRAKE '+(flight.brake?'ON':'OFF');$('#brake').classList.toggle('active',flight.brake);if(pilot){launchPilot=pilot.kind==='return'?new ReturnPilot():new LaunchPilot();launchPilot.done=pilot.done;launchPilot.released=pilot.released;$('#autoLaunch').textContent='自動実演を解除';}if(flight.physicsMigration)$('#centerNotice').textContent=physicsMigrationMessage(flight.physicsMigration);notify(physicsMigrationMessage(flight.physicsMigration)||('飛行を再開しました · T+ '+flight.time.toFixed(1)+'s'));return true;}catch(e){if(restored&&restored!==flight)restored.dispose();notify(e.message);return false;}}
