 const ownId=portOptions($('#ownPort'),own,flight.dockingPorts?.own),targetId=portOptions($('#targetPort'),other,flight.dockingPorts?.target);flight.dockingPorts=ownId&&targetId?{own:ownId,target:targetId}:null;
 const guide=flight.dockingPorts?portGuidance(flight,ownId,target,targetId):null,status=guide?dockingStatus(flight,ownId,target,targetId):null;
 $('#portGuide').hidden=!guide;$('#portFrame').checked=flight.portTranslationEnabled;
 if(guide){$('#portReadings').textContent='軸距離 '+guide.axial.toFixed(2)+' m · 横ずれ '+guide.lateral.toFixed(2)+' m · 接近 '+guide.closing.toFixed(2)+' m/s · 横速度 '+Math.hypot(guide.horizontalSpeed,guide.verticalSpeed).toFixed(2)+' m/s';const ctx=$('#portCrosshair').getContext('2d'),w=220,h=160,scale=Math.max(.5,Math.abs(guide.horizontal)*1.25,Math.abs(guide.vertical)*1.25);ctx.fillStyle='#14232a';ctx.fillRect(0,0,w,h);ctx.strokeStyle='#64818b';ctx.beginPath();ctx.moveTo(15,80);ctx.lineTo(205,80);ctx.moveTo(110,15);ctx.lineTo(110,145);ctx.stroke();ctx.strokeStyle='#79d1c2';ctx.beginPath();ctx.arc(110,80,Math.max(2,.15/scale*60),0,Math.PI*2);ctx.stroke();ctx.fillStyle='#ffb365';ctx.beginPath();ctx.arc(110+guide.horizontal/scale*60,80-guide.vertical/scale*60,5,0,Math.PI*2);ctx.fill();ctx.fillStyle='#cbdadf';ctx.font='11px sans-serif';ctx.fillText('自機のずれ / 目標面基準',8,12);ctx.fillText('範囲 ±'+scale.toFixed(1)+' m',8,154);}
