for(const id of ['ownPort','targetPort'])$('#'+id).onchange=()=>{if(flight)flight.dockingPorts={own:$('#ownPort').value,target:$('#targetPort').value};document.activeElement.blur();};
$('#portFrame').onchange=e=>{if(flight)flight.portTranslationEnabled=e.target.checked&&!!flight.dockingPorts;e.target.blur();};
$('#alignDock').onclick=()=>{if(!flight?.dockingPorts)return;flight.sasMode='dock';flight.sas=true;flight.holdQ=flight.q.clone();$('#sas').textContent='SAS ON';$('#sas').classList.add('active');document.activeElement.blur();};

function updateThermalInfo(){
 const current=flight?flight.parts:parts,shields=current.filter(p=>PARTS[p.type].heatShield),capacity=shields.reduce((n,p)=>n+PARTS[p.type].ablator,0),remaining=flight?shields.reduce((n,p)=>n+flight.thermal.get(p.id).ablator,0):capacity,list=$('#thermalParts');list.replaceChildren();
 $('#thermalSummary').textContent=capacity?'消耗材 '+remaining.toFixed(2)+' / '+capacity+' kg':'熱シールド未搭載';
 if(!flight)return;
 const ordered=[...current].sort((a,b)=>{const ratio=p=>flight.thermal.get(p.id).temperature/(PARTS[p.type].maxTemperature||1100);return ratio(b)-ratio(a);});
 for(const p of ordered){const state=flight.thermal.get(p.id),limit=PARTS[p.type].maxTemperature||1100,row=document.createElement('div');row.className='thermalRow'+(state.failed?' failed':state.temperature/limit>.8?' hot':'');row.textContent=PARTS[p.type].code+' · '+state.temperature.toFixed(0)+' / '+limit+' K'+(state.failed?' · 熱損傷':flight.telemetry.thermal?.parts.get(p.id)?.shielded?' · 遮熱中':'');list.append(row);}
}

let explorationError='';
function updateExploration(){
 if(!flight||!parkedWorld||practiceSession)return;
 try{
  const before=parkedWorld.history,next=recordLunarAchievements(recordOrbitAchievements(before,flight),flight);
  parkedWorld.history=next;explorationError='';
  for(const event of next.slice(before.length))notify(event.name+' · '+historyActionLabel(event));
 }catch(e){if(explorationError!==e.message){explorationError=e.message;notify('探査記録を保存できません：'+e.message);}}
}
function flightRecord(){updateExploration();const pilot=launchPilot?{kind:launchPilot instanceof ReturnPilot?'return':'launch',done:launchPilot.done,released:!!launchPilot.released}:null;return saveFlight(flight,{blueprint:parts.length?parts:flight.parts,name:flight.vesselName||activeFlightName||$('#craftName').value,pilot,worldHistory:parkedWorld?.history??[]});}
function parkFlight(){if(flight){universalTime=flight.universalTime;parkedWorld=worldFromFlight(flightRecord());}keys.clear();physicsClock.reset();}
function persistWorkspace(){
 if(workspaceError)return false;
 try{
  if(practiceSession){practiceSession.saveHome(localStorage);return true;}
  const world=flight?worldFromFlight(flightRecord()):parkedWorld??worldFromFlight(null,{universalTime});
  writeStoredGame(localStorage,gameRecord({world,draft:{parts,name:$('#craftName').value,bay:bayMode,environment:$('#environment').value}}));
  return true;
 }catch(e){$('#centerNotice').textContent='ブラウザへの保存に失敗しました。ページを閉じず、機体JSON出力・飛行保存を確認してください。';return false;}
}
function restoreWorkspace(){
 try{
  const saved=readStoredGame(localStorage);if(!saved)return;
  const {game,migrated}=saved,w=game.workshop,record=flightFromWorld(game.world),notices=[];
  if(migrated)notices.push('旧保存を読み込みました。次の自動保存から世界と設計を分けて記録します。旧保存はブラウザ内に残します。');
  if(record?.physicsMigration)notices.push(physicsMigrationMessage(record.physicsMigration));
  $('#centerNotice').textContent=notices.join(' ');
  universalTime=game.world.universalTime;parts=w.parts;$('#craftName').value=w.name;setBay(w.bay);$('#environment').value=w.environment;updateDepartureButton(document,w.environment);parkedWorld=game.world;
 }catch(e){
  workspaceError=true;$('#centerNotice').textContent='保存を復元できませんでした。元データを残して自動保存を停止しています。'+e.message;
  const reset=document.createElement('button');reset.textContent='元データを退避して新しく始める';
  reset.onclick=()=>{try{
   backupStoredGame(localStorage);workspaceError=false;
   if(!persistWorkspace()){workspaceError=true;throw Error('新しい保存を作成できませんでした');}
   $('#centerNotice').textContent='以前の保存をブラウザ内のバックアップへ退避しました。';reset.remove();
  }catch{workspaceError=true;reset.textContent='退避または保存に失敗しました。保存容量を確認してください';}};
  $('#centerNotice').after(reset);
 }
}
function refreshHistory(){
 const list=$('#worldHistoryRows');list.replaceChildren();const events=parkedWorld?.history??[];$('#worldHistoryCount').textContent=events.length;
 if(!events.length){const empty=document.createElement('p');empty.textContent='出発・回収・運用終了の記録はまだありません。旧保存の過去の操作は記録されません。';list.append(empty);return;}
 for(const event of [...events].reverse().slice(0,50)){const row=document.createElement('li');row.textContent=formatUniversalTime(event.universalTime)+' · '+event.name+' · '+historyActionLabel(event)+' · '+event.parts+'部品'+(event.type==='launch'?'':' · T+ '+event.missionTime.toFixed(1)+' s');list.append(row);}
 if(events.length>50){const note=document.createElement('p');note.textContent='最新50件を表示しています。過去の記録も保存しています。';list.append(note);}
}
function refreshCenter(){refreshHistory();$('#centerTime').textContent=formatUniversalTime(universalTime)+' · 共通時刻は停止中';let designCount=0,libraryError=false;try{designCount=loadDesigns().designs.length;}catch{libraryError=true;}const guide=$('#centerGuide');guide.replaceChildren();for(const item of centerGuidance({partCount:parts.length,designCount,vesselCount:parkedWorld?worldTrackingList(parkedWorld).length:0,libraryError,history:parkedWorld?.history??[]})){const row=document.createElement('li'),title=document.createElement('b'),text=document.createElement('span');title.textContent=item.title;text.textContent=item.text;row.classList.toggle('completed',item.completed);row.append(title,text);guide.append(row);}const name=$('#craftName').value;$('#centerDraft').textContent=name+' · '+parts.length+'部品 · '+bayMode.toUpperCase();const active=parkedWorld?.vessels.find(v=>v.vesselId===parkedWorld.activeVesselId)||parkedWorld?.vessels[0];$('#centerResume').disabled=!centerReady||!active;$('#centerFlightInfo').textContent=active?(active.vesselName||parkedWorld.flightMeta?.name||'機体')+' · T+ '+active.state.time.toFixed(1)+'s · '+active.parts.length+'部品 · 保持 '+parkedWorld.vessels.length+'機 · 一時停止中':'進行中の飛行はありません。';}
function showCenter(){if(practiceSession)finishPractice();else {parkFlight();if(flight)endFlight();}cancelPlacement();$('#orbitOverlay').hidden=true;atCenter=true;document.title='Orbital Foundry · 宇宙センター';document.body.classList.add('at-center');$('#spaceCenter').hidden=false;keys.clear();persistWorkspace();refreshCenter();centerView?.resize();}
function enterWorkshop(bay){if(!centerReady)return;atCenter=false;document.title='Orbital Foundry · '+bay.toUpperCase();$('#spaceCenter').hidden=true;document.body.classList.remove('at-center');setBay(bay);keys.clear();last=performance.now();resize();frame();persistWorkspace();}
function resumeFromCenter(selection=null){if(!parkedWorld?.vessels.length)return;const draft={parts,name:$('#craftName').value,environment:$('#environment').value,bay:bayMode};const record=flightFromWorld(selection?.world||parkedWorld);enterWorkshop(bayMode);if(restoreFlight(record)){parts=draft.parts;$('#craftName').value=draft.name;$('#environment').value=draft.environment;bayMode=draft.bay;parkedWorld=selection?.world||parkedWorld;if(selection?.observe){trackedDebris=fleet(flight).find(v=>v.vesselId===selection.observe);const focus=vesselCenter(trackedDebris);controls.target.copy(focus);camera.position.copy(focus).add(new T.Vector3(14,10,18));flightFocus.copy(focus);}persistWorkspace();}else showCenter();}
function requestLaunch(){launchAdditional({parts,name:$('#craftName').value,environment:$('#environment').value,bay:bayMode});}

async function initializeCenter(){centerReady=true;$('#enterVAB').disabled=false;$('#enterSPH').disabled=false;for(const id of ['centerTracking','centerPad','centerRunway'])$('#'+id).disabled=false;centerView=new SpaceCenter($('#centerScene'),openCenterFacility,highlightCenterFacility);try{await centerView.load();$('#centerLoading').hidden=true;}catch(e){$('#centerLoading').textContent='3D施設を読み込めませんでした。左のボタンから組立棟へ入れます。';console.error(e);}refreshCenter();}
$('#toCenter').onclick=showCenter;$('#enterVAB').onclick=()=>enterWorkshop('vab');$('#enterSPH').onclick=()=>enterWorkshop('sph');$('#centerResume').onclick=resumeFromCenter;
window.addEventListener('beforeunload',()=>{if(centerReady)persistWorkspace();});

function loadDesigns(){const raw=localStorage.getItem(DESIGN_LIBRARY_KEY);if(raw){if(raw.length>12000000)throw Error('設計一覧が大きすぎます');return readDesignLibrary(JSON.parse(raw));}const legacy=localStorage.getItem('orbital-foundry-craft');if(!legacy)return {version:1,designs:[]};const old=JSON.parse(legacy);return appendDesign({version:1,designs:[]},{name:typeof old.name==='string'?old.name:'以前の保存',parts:validateCraft(old),bay:'vab',environment:'land'},'legacy',0);}
function saveDesign(){try{const library=appendDesign(loadDesigns(),{name:$('#craftName').value,parts,bay:bayMode,environment:$('#environment').value});localStorage.setItem(DESIGN_LIBRARY_KEY,JSON.stringify(library));if(atCenter)refreshCenter();notify('設計一覧に新しい版を保存しました · '+library.designs.length+'件');return true;}catch(e){notify('保存できませんでした：'+e.message);return false;}}
$('#save').onclick=saveDesign;
function highlightCenterFacility(id){const facility=CENTER_FACILITIES[id];$('#centerFacilityName').textContent=facility?.name||'施設を選んで出発';$('#centerFacilityDescription').textContent=facility?.description||'建物にポインターを合わせると役割を表示します。';for(const [key,item]of Object.entries(CENTER_FACILITIES))$('#'+item.button).classList.toggle('facilityHighlighted',key===id);}
for(const [id,item]of Object.entries(CENTER_FACILITIES)){const button=$('#'+item.button);button.addEventListener('pointerenter',()=>centerView?.pointFacility(id));button.addEventListener('pointerleave',()=>centerView?.pointFacility(null));button.addEventListener('focus',()=>centerView?.focusFacility(id));button.addEventListener('blur',()=>centerView?.focusFacility(null));}
function openCenterFacility(id){if(id==='vab'||id==='sph'){enterWorkshop(id);return;}if(id==='tracking')openTracking();else if(id==='pad'||id==='runway')openLaunchLibrary(id);}
function openTracking(focusId=null){try{const rows=worldTrackingList(parkedWorld,{includeOrbit:true});showModal('<div class="eyebrow">TRACKING STATION</div><h2>追跡施設</h2><p>機体を選んで操縦・観察を再開します。選択するまでは時間が停止しています。</p><div id="trackingMapHost"></div><div id="trackingRows"></div>');$('#modal').classList.add('trackingDialog');const list=$('#trackingRows'),map=mountTrackingMap($('#trackingMapHost'),rows,id=>{for(const row of list.querySelectorAll('article'))row.classList.toggle('selectedVessel',row.dataset.vessel===id);});appendRecoveryUndo(list);if(!rows.length){const empty=document.createElement('p');empty.textContent='進行中の飛行はありません。VAB/SPHで機体を作って出発してください。';list.append(empty);return;}for(const [index,item]of rows.entries()){const row=document.createElement('article');row.className='facilityRow'+(index===0?' selectedVessel':'');row.dataset.vessel=item.id;row.style.setProperty('--vessel-color',TRACKING_COLORS[index%TRACKING_COLORS.length]);const name=document.createElement('strong'),description=document.createElement('p');name.textContent=(index+1)+'. '+item.name;const select=document.createElement('button');select.textContent='軌道図で選択';select.onclick=()=>{map.select(item.id);for(const other of list.querySelectorAll('article'))other.classList.toggle('selectedVessel',other===row);};row.append(select);description.textContent=item.parts+'部品 · 高度 '+(item.altitude/1000).toFixed(2)+' km · 軌道 '+item.speed.toFixed(1)+' m/s · 地表 '+item.surfaceSpeed.toFixed(1)+' m/s · T+ '+item.time.toFixed(1)+'s · '+item.status;row.append(name,description);for(const burn of item.pendingBurns){const note=document.createElement('p');note.textContent=burn.label+' · UT '+burn.time.toFixed(1)+' s · '+(burn.overdue?'予定時刻を過ぎています。操縦を再開して再計画・削除を確認':'噴射まで '+formatDuration(burn.time-item.universalTime));row.append(note);}for(const [observe,label]of [[false,'操縦を再開'],[true,'観察を再開']]){const button=document.createElement('button');button.textContent=label;button.disabled=!observe&&!item.controllable;button.onclick=()=>{try{const selection=selectWorldVessel(parkedWorld,item.id,{observe});$('#modal').close();resumeFromCenter(selection);}catch(e){$('#centerNotice').textContent=e.message;}};row.append(button);}const retire=document.createElement('button');retire.textContent=item.recovery.action;retire.onclick=()=>confirmRecovery(item);row.append(retire);list.append(row);if(item.id===focusId||item.anchorPartId===focusId){select.click();row.scrollIntoView({block:'center'});}}}catch(e){$('#centerNotice').textContent='追跡一覧を開けませんでした：'+e.message;}}
function openLaunchLibrary(facility){try{const library=loadDesigns();showModal('<div class="eyebrow">LAUNCH OPERATIONS</div><h2>'+ (facility==='workshop'?'保存した設計':facility==='pad'?'発射台':'滑走路')+'</h2><p>保存した設計の版を選びます。作業中の設計は保持されます。</p><button id="saveDraftToLibrary">作業中の設計を一覧に保存</button><div id="launchDesignRows"></div>');$('#saveDraftToLibrary').onclick=()=>{if(saveDesign())openLaunchLibrary(facility);else {const message=document.createElement('p');message.textContent='保存できませんでした。機体が空でないか、ブラウザの保存容量を確認してください。';$('#launchDesignRows').prepend(message);}};const list=$('#launchDesignRows');if(!library.designs.length){const empty=document.createElement('p');empty.textContent='まだ保存した設計がありません。上のボタンで現在の設計を保存できます。';list.append(empty);}for(const design of [...library.designs].reverse()){const row=document.createElement('article');row.className='facilityRow';const name=document.createElement('strong'),info=document.createElement('p'),button=document.createElement('button');name.textContent=design.name;info.textContent=design.parts.length+'部品 · '+design.bay.toUpperCase()+' · '+(design.savedAt?new Date(design.savedAt).toLocaleString():'以前の保存');button.textContent=facility==='workshop'?'設計を読み込む':facility==='pad'?'発射台から出発':'滑走路から出発';button.onclick=()=>{if(facility==='workshop'){if(flight)return;$('#modal').close();loadData({version:1,name:design.name,parts:design.parts});setBay(design.bay);$('#environment').value=design.environment;updateDepartureButton(document,design.environment);persistWorkspace();}else launchStoredDesign(library,design.id,facility);};row.append(name,info,button);list.append(row);}}catch(e){$('#centerNotice').textContent='設計一覧を開けませんでした：'+e.message;}}
function launchStoredDesign(library,id,facility){try{launchAdditional(designForLaunch(library,id,facility));}catch(e){$('#centerNotice').textContent=e.message;}}

$('#centerTracking').onclick=openTracking;$('#centerPad').onclick=()=>openLaunchLibrary('pad');$('#centerRunway').onclick=()=>openLaunchLibrary('runway');

$('#load').onclick=()=>{if(!flight)openLaunchLibrary('workshop');};

function finishPractice(){
 if(!practiceSession)return;
 const home=practiceSession.home;
 if(flight)endFlight();practiceSession=null;
 parkedWorld=home.world;universalTime=home.world.universalTime;
 parts=home.workshop.parts;$('#craftName').value=home.workshop.name;
 setBay(home.workshop.bay);$('#environment').value=home.workshop.environment;
 keys.clear();physicsClock.reset();rebuild();frame();updateInfo();
 notify('練習を終了しました。通常世界の機体・時刻・設計に戻りました。');
}
function launchAdditional(design){
 if(flight||practiceSession){notify('現在の飛行を終了してから出発してください');return;}
 let next=null,candidate=null;
 const draft={parts,name:$('#craftName').value,environment:$('#environment').value,bay:bayMode};
 try{
  const home=gameRecord({world:parkedWorld??worldFromFlight(null,{universalTime}),draft});
  const practice=departureMode(design.environment).mode==='practice';
  if(practice){
   if(workspaceError)throw Error('通常世界の保存エラーを解消してから練習を開始してください');
   candidate=new PracticeSession(home,design);candidate.saveHome(localStorage);
  }
  const launchedWorld=candidate?candidate.initialWorld:launchWorld(home.world,design);
  next=loadFlight(flightFromWorld(launchedWorld));
  practiceSession=candidate;$('#modal').close();enterWorkshop(design.bay||bayMode);
  parts=structuredClone(next.parts);$('#craftName').value=next.vesselName;
  $('#environment').value=next.environment;rebuild();startFlight(next);activeFlightName=next.vesselName;
  parkedWorld=launchedWorld;parts=draft.parts;$('#craftName').value=draft.name;
  $('#environment').value=draft.environment;bayMode=draft.bay;persistWorkspace();
  notify(practice?'独立した練習を開始しました。通常世界は停止・保持されています。':historyActionLabel(launchedWorld.history.at(-1))+' · 他の機体 '+(fleet(flight).length-1)+'機を保持');
 }catch(e){
  if(practiceSession){if(next===flight)next=null;finishPractice();}
  if(next&&next!==flight)next.dispose();
  parts=draft.parts;$('#craftName').value=draft.name;$('#environment').value=draft.environment;bayMode=draft.bay;
  $('#centerNotice').textContent=e.message;notify(e.message);
  if($('#modal').open){const message=document.createElement('p');message.textContent=e.message;$('#modalBody').append(message);}
 }
}

function appendRecoveryUndo(list){if(!recoveryUndo||JSON.stringify(parkedWorld)!==recoveryUndo.after)return;const text=document.createElement('p'),button=document.createElement('button');text.textContent=recoveryUndo.message+'。再開・追加出発・再読込するまでは取り消せます。';button.textContent='直前の回収・運用終了を取り消す';button.onclick=()=>{if(!recoveryUndo||JSON.stringify(parkedWorld)!==recoveryUndo.after)return;const after=parkedWorld;parkedWorld=structuredClone(recoveryUndo.before);if(!persistWorkspace()){parkedWorld=after;return;}recoveryUndo=null;refreshCenter();openTracking();};list.append(text,button);}
function confirmRecovery(item){showModal('<div class="eyebrow">MISSION OPERATIONS</div><h2 id="retireTitle"></h2><p id="retireSummary"></p><p>この機体だけを飛行一覧から外します。保存設計と他の機体は保持します。直後に取り消せますが、再開・追加出発・再読込後は取り消せません。</p><button id="confirmRetire">実行</button><button id="cancelRetire">戻る</button>');$('#retireTitle').textContent=item.recovery.action+'の確認';$('#retireSummary').textContent=item.name+' · '+item.parts+'部品 · '+item.recovery.reason;$('#cancelRetire').onclick=openTracking;$('#confirmRetire').onclick=()=>{try{const before=structuredClone(parkedWorld),result=retireWorldVessel(parkedWorld,item.id,item.recovery.recoverable?'recover':'terminate');parkedWorld=result.world;if(!persistWorkspace()){parkedWorld=before;throw Error('保存できなかったため機体を保持しました');}recoveryUndo={before,after:JSON.stringify(parkedWorld),message:result.removed.name+'を'+result.removed.action+'しました'};refreshCenter();openTracking();}catch(e){$('#retireSummary').textContent=e.message;}};}

function branchGhost(branch){const group=new T.Group(),preview=placeBranch([],branch,{position:[0,0,0],rotation:[0,0,0]});for(const p of preview.parts){const model=cloneModel(p.type);model.position.fromArray(p.p);model.rotation.set(...p.r);group.add(model);}return group;}
function renderAssemblyTree(){const panel=$('#assemblyTree'),list=$('#assemblyTreeRows');panel.hidden=!!flight;const scroll=list.scrollTop;list.replaceChildren();if(flight)return;const branch=selected?descendants(parts,selected):new Set();for(const [index,item]of assemblyTree(parts).entries()){const row=document.createElement('li'),button=document.createElement('button');row.style.paddingLeft=Math.min(item.depth,12)*12+'px';button.textContent=(index+1)+'. '+PARTS[item.type].code+' '+PARTS[item.type].name+' · 枝'+item.count+' · 段'+item.stage;button.classList.toggle('branchMember',branch.has(item.id));button.setAttribute('aria-pressed',String(item.id===selected));button.onclick=()=>{cancelPlacement();select(item.id);};row.append(button);list.append(row);}list.scrollTop=scroll;$('#assemblyTreeCount').textContent=parts.length;}

function clearInterferenceHighlight(){for(const o of [...interferenceOverlay.children]){o.geometry.dispose();o.material.dispose();interferenceOverlay.remove(o);}for(const row of document.querySelectorAll('.interferencePairActive'))row.classList.remove('interferencePairActive');}
function showInterferencePair(pair,focusId,row){if(flight)return;cancelPlacement();select(focusId);for(const [index,id]of [pair.a,pair.b].entries()){const p=parts.find(p=>p.id===id);if(!p)continue;const box=orientedBounds(p,assetBounds.get(p.type)),shape=new T.BoxGeometry(...box.half.clone().multiplyScalar(2).toArray()),edges=new T.EdgesGeometry(shape);shape.dispose();const line=new T.LineSegments(edges,new T.LineBasicMaterial({color:index?'#55dce8':'#ff9c56',depthTest:false}));line.position.copy(box.center);line.quaternion.copy(box.quaternion);line.renderOrder=20;interferenceOverlay.add(line);}row.classList.add('interferencePairActive');}
function renderInterferences(){const list=$('#interferenceRows');list.replaceChildren();if(flight)return;const result=assemblyInterferences(parts,assetBounds);$('#interferenceCount').textContent=result.total;$('#interferenceSummary').textContent=result.total?(result.total+' 組。'+(result.total>result.pairs.length?'先頭 '+result.pairs.length+' 組を表示。':'')+'部品名を選ぶと橙・水色の箱で表示します。'):'箱同士の明確な重なりはありません。';const indices=new Map(parts.map((p,i)=>[p.id,i+1]));for(const pair of result.pairs){const row=document.createElement('article');row.className='interferencePair';for(const [index,id]of [pair.a,pair.b].entries()){const p=parts.find(p=>p.id===id),button=document.createElement('button');button.textContent=(index?'水色':'橙')+' '+indices.get(id)+'. '+PARTS[p.type].code+' '+PARTS[p.type].name;button.onclick=()=>showInterferencePair(pair,id,row);row.append(button);}list.append(row);}}

function updateWorkshop(){if(flight)return;const bounds=new T.Box3().setFromObject(craftRoot),layout=workshopLayout(bounds);bay.position.fromArray(layout.origin);workshopFloor=layout.origin[1];room.scale.fromArray(layout.roomScale);workshopDeck.scale.set(layout.platformScale,1,layout.platformScale);workshopGround.scale.set((layout.gridSize+10)/90,1,(layout.gridSize+10)/90);if(workshopGridSize!==layout.gridSize){grid.removeFromParent();grid.geometry.dispose();for(const material of Array.isArray(grid.material)?grid.material:[grid.material])material.dispose();workshopGridSize=layout.gridSize;const step=Math.max(1,Math.ceil(workshopGridSize/200));grid=new T.GridHelper(workshopGridSize,Math.ceil(workshopGridSize/step),'#647984','#435963');grid.position.y=-.16;bay.add(grid);}const fit=workshopFrame(bounds,camera.fov,camera.aspect);if(fit){controls.maxDistance=fit.maxDistance;scene.fog=new T.Fog('#293c49',fit.fogNear,fit.fogFar);}}

const capturePanel=mountCapturePanel(document.querySelector('#transferPanel'),()=>flight,message=>{syncFlightControls();notify(message);});
const descentPanel=mountDescentPanel(document.querySelector('#capturePanel'),()=>flight,()=>syncFlightControls());
mountFlightLayout();
const ascentPanel=mountAscentPanel(document.querySelector('#descentPanel'),()=>flight,()=>syncFlightControls());
const departurePanel=mountDeparturePanel(document.querySelector('#ascentPanel'),()=>flight,message=>{syncFlightControls();if(message)notify(message);});
const stageVisibility=mountStageVisibility(()=>objects);
const designDiagnostics=mountDesignDiagnostics($('#checks'),()=>({parts,flight}),id=>{cancelPlacement();select(id);$('#selection').scrollIntoView({block:'nearest'});},balance=>thrustOverlay.update(balance),ids=>stageVisibility.update(ids));
const returnPanel=mountReturnPanel(document.querySelector('#ascentPanel'),()=>flight,message=>{syncFlightControls();if(message)notify(message);},{isPractice:()=>!!practiceSession});
const trajectoryPanel=mountTrajectoryPanel(document.querySelector('.mapContent'),()=>{
 if(!flight)return null;let burn=null,note='';const time=flight.universalTime;
 if(document.querySelector('#planEnabled').checked){const preview=maneuverPreview(flightCenter(),flight.vel,document.querySelector('#planLocation').value,Number(document.querySelector('#planDeltaV').value),time);burn={time:preview.universalTime,deltaV:preview.impulse.toArray()};}
 else if(flight.maneuver&&!flight.maneuver.complete){const node=flight.maneuver,burnTime=node.capture?.midTime??node.returnPlan?.midTime??node.departure?.midTime??node.universalTime??time+node.time-flight.time;if(burnTime>=time)burn={time:burnTime,deltaV:[...node.remaining]};else note='固定計画は過去のため比較対象外';}
 return {position:flightCenter().clone(),velocity:flight.vel.clone(),time,burn,note,name:flight.vesselName||'機体'};
});

function updateTransferGuide(){const g=flight?.transferGuide,panel=document.querySelector('#transferPanel');panel.hidden=!g;if(!g)return;const until=g.startTime-flight.universalTime,remaining=g.target-g.delivered,early=g.firstBurnTime!==null?g.firstBurnTime-g.startTime:null;
 document.querySelector('#transferStatus').textContent=g.firstBurnTime===null?(until>0?'噴射開始まで '+until.toFixed(1)+'秒 · SAS順行・スロットル0で待機':'噴射時刻です（'+(-until).toFixed(1)+'秒経過）'):remaining<=0?(flight.throttle>0?'目標Δv到達 — 今すぐ噴射停止':'噴射完了。軌道マップで接近予測を再計算してください'):(remaining<100?'10%へ絞って調整 · 残り ':'噴射中 · 残り ')+remaining.toFixed(1)+' m/s';
 document.querySelector('#transferProgress').textContent='順行噴射量 '+g.delivered.toFixed(1)+' / '+g.target.toFixed(1)+' m/s · 全開の目安 '+g.burnTime.toFixed(1)+'秒'+(early!==null&&Math.abs(early)>2?' · 開始ずれ '+early.toFixed(1)+'秒：到達は再予測が必要':'');
 document.querySelector('#transferIgnite').disabled=!canControl(flight)||flight.crashed;
}
document.querySelector('#transferIgnite').onclick=()=>{if(!flight||!canControl(flight)||flight.crashed)return;if(flight.stage<0)stage();flight.throttle=1;document.querySelector('#throttle').value=100;updateTransferGuide();};
document.querySelector('#transferCutoff').onclick=()=>{if(!flight)return;flight.throttle=0;document.querySelector('#throttle').value=0;updateTransferGuide();};

document.querySelector('#transferFine').onclick=()=>{if(!flight||!canControl(flight)||flight.crashed)return;flight.throttle=.1;document.querySelector('#throttle').value=10;updateTransferGuide();};
